import 'package:flutter/foundation.dart';

class WordTimestamp {
  final String word;
  final double start;
  final double end;

  const WordTimestamp({
    required this.word,
    required this.start,
    required this.end,
  });

  factory WordTimestamp.fromJson(Map<String, dynamic> json) {
    return WordTimestamp(
      word: json['word'] as String? ?? '',
      start: (json['start'] as num?)?.toDouble() ?? 0,
      end: (json['end'] as num?)?.toDouble() ?? 0,
    );
  }
}

class TextElement {
  final String id;
  final String text;
  final double x;
  final double y;
  final double width;
  final String fontFamily;
  final double fontSize;
  final int fontWeight;
  final String color;
  final String textAlign;
  final double rotation;
  final TextShadow? shadow;
  final TextBackground? background;

  const TextElement({
    required this.id,
    required this.text,
    required this.x,
    required this.y,
    required this.width,
    required this.fontFamily,
    required this.fontSize,
    required this.fontWeight,
    required this.color,
    required this.textAlign,
    required this.rotation,
    this.shadow,
    this.background,
  });

  factory TextElement.fromJson(Map<String, dynamic> json) {
    return TextElement(
      id: json['id'] as String? ?? '',
      text: json['text'] as String? ?? '',
      x: (json['x'] as num?)?.toDouble() ?? 0,
      y: (json['y'] as num?)?.toDouble() ?? 0,
      width: (json['width'] as num?)?.toDouble() ?? 0,
      fontFamily: json['fontFamily'] as String? ?? 'Inter',
      fontSize: (json['fontSize'] as num?)?.toDouble() ?? 0,
      fontWeight: (json['fontWeight'] as num?)?.toInt() ?? 400,
      color: json['color'] as String? ?? '#FFFFFF',
      textAlign: json['textAlign'] as String? ?? 'left',
      rotation: (json['rotation'] as num?)?.toDouble() ?? 0,
      shadow: json['shadow'] is Map<String, dynamic>
          ? TextShadow.fromJson(json['shadow'] as Map<String, dynamic>)
          : null,
      background: json['background'] is Map<String, dynamic>
          ? TextBackground.fromJson(json['background'] as Map<String, dynamic>)
          : null,
    );
  }
}

class TextShadow {
  final String color;
  final double blur;
  final double x;
  final double y;

  const TextShadow({
    required this.color,
    required this.blur,
    required this.x,
    required this.y,
  });

  factory TextShadow.fromJson(Map<String, dynamic> json) {
    return TextShadow(
      color: json['color'] as String? ?? '#000000',
      blur: (json['blur'] as num?)?.toDouble() ?? 0,
      x: (json['x'] as num?)?.toDouble() ?? 0,
      y: (json['y'] as num?)?.toDouble() ?? 0,
    );
  }
}

class TextBackground {
  final String color;
  final double? padding;
  final double? borderRadius;

  const TextBackground({required this.color, this.padding, this.borderRadius});

  factory TextBackground.fromJson(Map<String, dynamic> json) {
    return TextBackground(
      color: json['color'] as String? ?? '#000000',
      padding: (json['padding'] as num?)?.toDouble(),
      borderRadius: (json['borderRadius'] as num?)?.toDouble(),
    );
  }
}

class TextOverlayConfig {
  final int version;
  final List<TextElement> elements;

  const TextOverlayConfig({required this.version, required this.elements});

  factory TextOverlayConfig.fromJson(Map<String, dynamic> json) {
    final elements = (json['elements'] as List<dynamic>? ?? <dynamic>[])
        .whereType<Map<String, dynamic>>()
        .map(TextElement.fromJson)
        .toList();

    return TextOverlayConfig(
      version: (json['version'] as num?)?.toInt() ?? 1,
      elements: elements,
    );
  }
}

class PageData {
  final String id;
  final int pageNumber;
  final String? textContent;
  final TextOverlayConfig? overlay;
  final String? imageUrl;
  final String? narrationUrl;
  final String? soundscapeUrl;
  final String? compositedImageUrl;
  final List<WordTimestamp>? narrationTimestamps;

  const PageData({
    required this.id,
    required this.pageNumber,
    this.textContent,
    this.overlay,
    this.imageUrl,
    this.narrationUrl,
    this.soundscapeUrl,
    this.compositedImageUrl,
    this.narrationTimestamps,
  });

  factory PageData.fromJson(Map<String, dynamic> json) {
    final rawTimestamps =
        json['narration_timestamps'] ?? json['narrationTimestamps'];
    final timestamps = rawTimestamps is List
        ? rawTimestamps
              .whereType<Map<String, dynamic>>()
              .map(WordTimestamp.fromJson)
              .toList()
        : null;

    final overlayJson = json['text_overlay'];

    // Soundscape URL is derived from the nested scenes -> soundscapes relation.
    // Prefer admin-approved soundscapes, fall back to first available.
    String? soundscapeUrl;
    final scenesData = json['scenes'];
    if (scenesData is Map<String, dynamic>) {
      final rawSoundscapes = scenesData['soundscapes'];
      if (rawSoundscapes is List && rawSoundscapes.isNotEmpty) {
        final soundscapes = rawSoundscapes
            .whereType<Map<String, dynamic>>()
            .toList();
        final approved = soundscapes
            .where((s) => s['admin_approved'] == true)
            .toList();
        final chosen = approved.isNotEmpty ? approved.first : soundscapes.first;
        soundscapeUrl = chosen['audio_url'] as String?;
      }
    }

    return PageData(
      id: json['id']?.toString() ?? '',
      pageNumber: _parsePageNumber(json),
      textContent:
          json['text_content'] as String? ?? json['textContent'] as String?,
      overlay: overlayJson is Map<String, dynamic>
          ? TextOverlayConfig.fromJson(overlayJson)
          : null,
      imageUrl: json['image_url'] as String? ?? json['imageUrl'] as String?,
      narrationUrl:
          json['narration_url'] as String? ?? json['narrationUrl'] as String?,
      soundscapeUrl: soundscapeUrl,
      compositedImageUrl:
          json['composited_image_url'] as String? ??
          json['compositedImageUrl'] as String?,
      narrationTimestamps: timestamps,
    );
  }
}

class Book {
  final String id;
  final String title;
  final String? author;
  final String? coverUrl;
  final List<PageData> pages;

  const Book({
    required this.id,
    required this.title,
    this.author,
    this.coverUrl,
    required this.pages,
  });

  factory Book.fromJson(Map<String, dynamic> json) {
    final parsedPages = (json['pages'] as List<dynamic>? ?? <dynamic>[])
        .whereType<Map<String, dynamic>>()
        .map(PageData.fromJson)
        .toList();

    final pages = _sortedPages(parsedPages);
    assert(() {
      if (_isDifferentOrder(parsedPages, pages)) {
        debugPrint(
          '[Book.fromJson] Incoming page order was unsorted for book '
          '${json['id'] ?? ''}. Applying deterministic sort by pageNumber/id.',
        );
      }
      return true;
    }());

    return Book(
      id: json['id']?.toString() ?? '',
      title: json['title'] as String? ?? '',
      author: json['author'] as String?,
      coverUrl: json['cover_url'] as String? ?? json['coverUrl'] as String?,
      pages: pages,
    );
  }
}

const int _invalidPageNumber = 1 << 30;

int _parsePageNumber(Map<String, dynamic> json) {
  final rawPageNumber = json['page_number'] ?? json['pageNumber'];
  if (rawPageNumber is num) {
    final pageNumber = rawPageNumber.toInt();
    return pageNumber > 0 ? pageNumber : _invalidPageNumber;
  }
  if (rawPageNumber is String) {
    final pageNumber = int.tryParse(rawPageNumber);
    if (pageNumber == null || pageNumber <= 0) {
      return _invalidPageNumber;
    }
    return pageNumber;
  }
  return _invalidPageNumber;
}

List<PageData> _sortedPages(List<PageData> pages) {
  final indexedPages = pages.asMap().entries.toList();
  indexedPages.sort((a, b) {
    final pageNumberCompare = a.value.pageNumber.compareTo(b.value.pageNumber);
    if (pageNumberCompare != 0) {
      return pageNumberCompare;
    }

    final idCompare = a.value.id.compareTo(b.value.id);
    if (idCompare != 0) {
      return idCompare;
    }

    return a.key.compareTo(b.key);
  });

  return indexedPages.map((entry) => entry.value).toList(growable: false);
}

bool _isDifferentOrder(List<PageData> original, List<PageData> sorted) {
  if (identical(original, sorted)) {
    return false;
  }
  if (original.length != sorted.length) {
    return true;
  }
  for (var i = 0; i < original.length; i++) {
    if (!identical(original[i], sorted[i])) {
      return true;
    }
  }
  return false;
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:google_fonts/google_fonts.dart';

import '../../audio/audio_providers.dart';
import '../../data/models.dart';
import '../../data/providers.dart';
import 'page_renderer.dart';

class ReaderScreen extends ConsumerStatefulWidget {
  final String bookId;

  const ReaderScreen({super.key, required this.bookId});

  @override
  ConsumerState<ReaderScreen> createState() => _ReaderScreenState();
}

class _ReaderScreenState extends ConsumerState<ReaderScreen> {
  final PageController _pageController = PageController();
  final ValueNotifier<Duration> _narrationPositionNotifier = ValueNotifier(
    Duration.zero,
  );
  int _activePageIndex = 0;
  bool _isPlaying = false;
  bool _showChrome = true;
  bool _loadedInitialAudio = false;
  double _narrationVolume = 1;
  double _soundscapeVolume = 0.6;
  StreamSubscription<Duration>? _positionSubscription;
  StreamSubscription<bool>? _playingSubscription;

  @override
  void initState() {
    super.initState();
    final audioEngine = ref.read(audioEngineProvider);
    audioEngine.ensureInitialized();

    _positionSubscription = audioEngine.narrationPosition.listen((position) {
      if (!mounted) {
        return;
      }
      _narrationPositionNotifier.value = position;
    });

    _playingSubscription = audioEngine.narrationPlaying.listen((playing) {
      if (!mounted) {
        return;
      }
      setState(() {
        _isPlaying = playing;
      });
    });
  }

  @override
  void dispose() {
    _positionSubscription?.cancel();
    _playingSubscription?.cancel();
    _narrationPositionNotifier.dispose();
    _pageController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bookAsync = ref.watch(currentBookProvider(widget.bookId));
    final audioEngine = ref.watch(audioEngineProvider);

    return Scaffold(
      backgroundColor: const Color(0xFF121A24),
      body: bookAsync.when(
        data: (book) {
          if (book == null) {
            return const Center(child: Text('Book not found'));
          }

          if (book.pages.isEmpty) {
            return const Center(child: Text('No pages in this book'));
          }

          if (_activePageIndex >= book.pages.length) {
            _activePageIndex = book.pages.length - 1;
          }

          final activePage = book.pages[_activePageIndex];

          if (!_loadedInitialAudio) {
            _loadedInitialAudio = true;
            WidgetsBinding.instance.addPostFrameCallback((_) async {
              await audioEngine.loadPage(book.pages[_activePageIndex]);
            });
          }

          return Stack(
            children: [
              GestureDetector(
                behavior: HitTestBehavior.translucent,
                onTap: () => setState(() => _showChrome = !_showChrome),
                child: PageView.builder(
                  controller: _pageController,
                  scrollDirection: Axis.vertical,
                  itemCount: book.pages.length,
                  onPageChanged: (index) async {
                    setState(() {
                      _activePageIndex = index;
                    });
                    await audioEngine.transitionToPage(book.pages[index]);
                  },
                  itemBuilder: (context, index) {
                    final isInVirtualizationWindow =
                        (index - _activePageIndex).abs() <= 1;
                    if (!isInVirtualizationWindow) {
                      return const SizedBox.shrink();
                    }
                    final page = book.pages[index];
                    return ValueListenableBuilder<Duration>(
                      valueListenable: _narrationPositionNotifier,
                      builder: (context, narrationPosition, child) {
                        return PageRenderer(
                          page: page,
                          narrationPosition: narrationPosition,
                          isActive: index == _activePageIndex,
                        );
                      },
                    );
                  },
                ),
              ),
              IgnorePointer(
                ignoring: !_showChrome,
                child: AnimatedOpacity(
                  opacity: _showChrome ? 1 : 0,
                  duration: 220.ms,
                  curve: Curves.easeOut,
                  child: _ReaderChrome(
                    book: book,
                    activePageIndex: _activePageIndex,
                    activePageNumber: activePage.pageNumber,
                    isPlaying: _isPlaying,
                    onClose: () => Navigator.of(context).maybePop(),
                    onPlayPause: () async {
                      if (_isPlaying) {
                        await audioEngine.pause();
                      } else {
                        await audioEngine.play();
                      }
                    },
                    onAudioSettingsTap: () =>
                        _showAudioSettings(context, audioEngine),
                  ),
                ),
              ),
            ],
          );
        },
        loading: () => const _ReaderLoadingState(),
        error: (error, _) => _ReaderErrorState(error: '$error'),
      ),
    );
  }

  Future<void> _showAudioSettings(BuildContext context, dynamic audioEngine) {
    return showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFFF9F8F4),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setModalState) {
            return Padding(
              padding: const EdgeInsets.fromLTRB(18, 18, 18, 28),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 46,
                      height: 5,
                      decoration: BoxDecoration(
                        color: const Color(0xFFD7D7D2),
                        borderRadius: BorderRadius.circular(999),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'Audio Mix',
                    style: GoogleFonts.playfairDisplay(
                      fontSize: 26,
                      fontWeight: FontWeight.w700,
                      color: const Color(0xFF2E2A3D),
                    ),
                  ),
                  const SizedBox(height: 18),
                  _VolumeRow(
                    icon: Icons.record_voice_over_rounded,
                    label: 'Narration',
                    value: _narrationVolume,
                    onChanged: (value) async {
                      setModalState(() => _narrationVolume = value);
                      setState(() => _narrationVolume = value);
                      await audioEngine.setNarrationVolume(value);
                    },
                  ),
                  const SizedBox(height: 14),
                  _VolumeRow(
                    icon: Icons.surround_sound_rounded,
                    label: 'Ambience',
                    value: _soundscapeVolume,
                    onChanged: (value) async {
                      setModalState(() => _soundscapeVolume = value);
                      setState(() => _soundscapeVolume = value);
                      await audioEngine.setSoundscapeVolume(value);
                    },
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

class _ReaderChrome extends StatelessWidget {
  final Book book;
  final int activePageIndex;
  final int activePageNumber;
  final bool isPlaying;
  final VoidCallback onClose;
  final Future<void> Function() onPlayPause;
  final VoidCallback onAudioSettingsTap;

  const _ReaderChrome({
    required this.book,
    required this.activePageIndex,
    required this.activePageNumber,
    required this.isPlaying,
    required this.onClose,
    required this.onPlayPause,
    required this.onAudioSettingsTap,
  });

  @override
  Widget build(BuildContext context) {
    final topInset = MediaQuery.paddingOf(context).top;
    final bottomInset = MediaQuery.paddingOf(context).bottom;

    return Stack(
      children: [
        Positioned(
          left: 0,
          right: 0,
          top: 0,
          child: IgnorePointer(
            child: Container(
              height: topInset + 110,
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [Color.fromRGBO(8, 12, 17, 0.75), Colors.transparent],
                ),
              ),
            ),
          ),
        ),
        Positioned(
          top: topInset + 10,
          left: 14,
          right: 14,
          child: Row(
            children: [
              _ChromeButton(
                icon: Icons.arrow_back_ios_new_rounded,
                onTap: onClose,
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 9,
                  ),
                  decoration: BoxDecoration(
                    color: const Color.fromRGBO(10, 16, 26, 0.58),
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: const Color.fromRGBO(255, 255, 255, 0.2),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        book.title,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: GoogleFonts.lora(
                          fontSize: 14,
                          fontWeight: FontWeight.w700,
                          color: Colors.white,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        'Page $activePageNumber of ${book.pages.length}',
                        style: GoogleFonts.inter(
                          fontSize: 12,
                          fontWeight: FontWeight.w600,
                          color: const Color(0xFFD4D8E0),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
        Positioned(
          left: 0,
          right: 0,
          bottom: 0,
          child: IgnorePointer(
            child: Container(
              height: bottomInset + 160,
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [Colors.transparent, Color.fromRGBO(8, 12, 17, 0.8)],
                ),
              ),
            ),
          ),
        ),
        Positioned(
          left: 14,
          right: 14,
          bottom: bottomInset + 12,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            decoration: BoxDecoration(
              color: const Color.fromRGBO(10, 16, 26, 0.62),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: const Color.fromRGBO(255, 255, 255, 0.16),
              ),
            ),
            child: Row(
              children: [
                _ChromeButton(
                  icon: isPlaying
                      ? Icons.pause_rounded
                      : Icons.play_arrow_rounded,
                  onTap: () async => onPlayPause(),
                  isPrimary: true,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: AnimatedSwitcher(
                    duration: 220.ms,
                    child: Text(
                      key: ValueKey<int>(activePageIndex),
                      'Now reading page $activePageNumber',
                      style: GoogleFonts.inter(
                        fontSize: 13,
                        fontWeight: FontWeight.w600,
                        color: const Color(0xFFE7EBF2),
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 8),
                _ChromeButton(
                  icon: Icons.tune_rounded,
                  onTap: onAudioSettingsTap,
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }
}

class _ChromeButton extends StatelessWidget {
  final IconData icon;
  final VoidCallback onTap;
  final bool isPrimary;

  const _ChromeButton({
    required this.icon,
    required this.onTap,
    this.isPrimary = false,
  });

  @override
  Widget build(BuildContext context) {
    return Material(
      color: isPrimary
          ? const Color(0xFF6F61C7)
          : const Color.fromRGBO(255, 255, 255, 0.14),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(12),
        side: isPrimary
            ? BorderSide.none
            : const BorderSide(color: Color.fromRGBO(255, 255, 255, 0.18)),
      ),
      child: InkWell(
        borderRadius: BorderRadius.circular(12),
        onTap: onTap,
        child: SizedBox(
          width: 42,
          height: 42,
          child: Icon(icon, color: Colors.white, size: 21),
        ),
      ),
    );
  }
}

class _VolumeRow extends StatelessWidget {
  final IconData icon;
  final String label;
  final double value;
  final ValueChanged<double> onChanged;

  const _VolumeRow({
    required this.icon,
    required this.label,
    required this.value,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: const Color(0xFFE4E4DE)),
      ),
      child: Row(
        children: [
          Icon(icon, size: 20, color: const Color(0xFF585374)),
          const SizedBox(width: 10),
          SizedBox(
            width: 72,
            child: Text(
              label,
              style: GoogleFonts.inter(
                fontSize: 13,
                fontWeight: FontWeight.w700,
                color: const Color(0xFF2E2A3D),
              ),
            ),
          ),
          Expanded(
            child: SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 4,
                thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 7),
              ),
              child: Slider(
                value: value,
                min: 0,
                max: 1,
                activeColor: const Color(0xFF6F61C7),
                onChanged: onChanged,
              ),
            ),
          ),
          Text(
            '${(value * 100).round()}%',
            style: GoogleFonts.inter(
              fontSize: 12,
              fontWeight: FontWeight.w700,
              color: const Color(0xFF6B7280),
            ),
          ),
        ],
      ),
    );
  }
}

class _ReaderLoadingState extends StatelessWidget {
  const _ReaderLoadingState();

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const CircularProgressIndicator(color: Color(0xFF8A80CC)),
          const SizedBox(height: 14),
          Text(
            'Opening your story...',
            style: GoogleFonts.inter(
              color: const Color(0xFFC5CBD8),
              fontWeight: FontWeight.w600,
            ),
          ),
        ],
      ),
    );
  }
}

class _ReaderErrorState extends StatelessWidget {
  final String error;

  const _ReaderErrorState({required this.error});

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(
              Icons.auto_stories_rounded,
              color: Color(0xFFC5CBD8),
              size: 34,
            ),
            const SizedBox(height: 12),
            Text(
              'This story could not be loaded',
              style: GoogleFonts.inter(
                color: Colors.white,
                fontWeight: FontWeight.w700,
                fontSize: 16,
              ),
            ),
            const SizedBox(height: 8),
            Text(
              error,
              textAlign: TextAlign.center,
              style: GoogleFonts.inter(
                color: const Color(0xFFC5CBD8),
                fontSize: 12,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';
import 'package:google_fonts/google_fonts.dart';

import '../../core/resilient_cache_manager.dart';
import '../../data/models.dart';
import 'overlay/overlay_text_layer.dart';
import 'overlay/text_overlay_utils.dart';

class PageRenderer extends StatefulWidget {
  final PageData page;
  final Duration narrationPosition;
  final bool isActive;
  final void Function(String word, int globalIndex)? onWordTap;

  const PageRenderer({
    super.key,
    required this.page,
    required this.narrationPosition,
    required this.isActive,
    this.onWordTap,
  });

  @override
  State<PageRenderer> createState() => _PageRendererState();
}

class _PageRendererState extends State<PageRenderer> {
  Size? _sourceImageSize;

  @override
  void initState() {
    super.initState();
    _resolveImageDimensions();
  }

  @override
  void didUpdateWidget(covariant PageRenderer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.page.imageUrl != widget.page.imageUrl) {
      _sourceImageSize = null;
      _resolveImageDimensions();
    }
  }

  Future<void> _resolveImageDimensions() async {
    final imageUrl = widget.page.imageUrl;
    if (imageUrl == null || imageUrl.isEmpty) {
      return;
    }

    final completer = Completer<Size>();
    final stream = CachedNetworkImageProvider(
      imageUrl,
      cacheManager: ResilientCacheManager.instance,
    ).resolve(const ImageConfiguration());
    late final ImageStreamListener listener;
    listener = ImageStreamListener(
      (image, _) {
        if (!completer.isCompleted) {
          completer.complete(
            Size(image.image.width.toDouble(), image.image.height.toDouble()),
          );
        }
        stream.removeListener(listener);
      },
      onError: (_, __) {
        if (!completer.isCompleted) {
          completer.complete(Size.zero);
        }
        stream.removeListener(listener);
      },
    );

    stream.addListener(listener);
    final size = await completer.future;
    if (!mounted) {
      return;
    }
    setState(() {
      _sourceImageSize = size;
    });
  }

  @override
  Widget build(BuildContext context) {
    final page = widget.page;
    final hasOverlay =
        page.overlay != null && page.overlay!.elements.isNotEmpty;
    final hasFallbackText =
        (page.textContent ?? '').trim().isNotEmpty &&
        (page.imageUrl ?? '').isNotEmpty;

    return LayoutBuilder(
      builder: (context, constraints) {
        final container = Size(constraints.maxWidth, constraints.maxHeight);
        final sourceImageSize = _sourceImageSize;
        final imageRect = hasOverlay && sourceImageSize != null
            ? computeContainedImageRect(
                container: container,
                sourceImage: sourceImageSize,
              )
            : Rect.fromLTWH(0, 0, container.width, container.height);

        final activeWordIndex = computeActiveWordIndex(
          page.narrationTimestamps,
          widget.narrationPosition,
        );

        return Stack(
          fit: StackFit.expand,
          children: [
            if (page.imageUrl != null && page.imageUrl!.isNotEmpty)
              Image(
                image: CachedNetworkImageProvider(
                  page.imageUrl!,
                  cacheManager: ResilientCacheManager.instance,
                ),
                fit: hasOverlay ? BoxFit.contain : BoxFit.cover,
                width: double.infinity,
                height: double.infinity,
              )
            else
              const ColoredBox(color: Color(0xFFDDDDD4)),
            if (hasOverlay && page.overlay != null && imageRect != Rect.zero)
              Positioned(
                left: imageRect.left,
                top: imageRect.top,
                width: imageRect.width,
                height: imageRect.height,
                child: OverlayTextLayer(
                  overlay: page.overlay!,
                  imageSize: imageRect.size,
                  activeWordIndex: activeWordIndex,
                  isActive: widget.isActive,
                  onWordTap: widget.onWordTap,
                ),
              ),
            if (!hasOverlay && hasFallbackText)
              Align(
                alignment: Alignment.bottomCenter,
                child: Container(
                  width: double.infinity,
                  padding: const EdgeInsets.fromLTRB(18, 24, 18, 112),
                  decoration: const BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                      colors: [
                        Colors.transparent,
                        Color.fromRGBO(3, 8, 16, 0.56),
                        Color.fromRGBO(2, 6, 12, 0.9),
                      ],
                      stops: [0, 0.33, 1],
                    ),
                  ),
                  child: Center(
                    child: ConstrainedBox(
                      constraints: const BoxConstraints(maxWidth: 560),
                      child:
                          DecoratedBox(
                                decoration: BoxDecoration(
                                  color: const Color.fromRGBO(10, 18, 28, 0.52),
                                  borderRadius: BorderRadius.circular(18),
                                  border: Border.all(
                                    color: const Color.fromRGBO(
                                      255,
                                      255,
                                      255,
                                      0.2,
                                    ),
                                  ),
                                  boxShadow: const [
                                    BoxShadow(
                                      color: Color.fromRGBO(0, 0, 0, 0.24),
                                      blurRadius: 18,
                                      offset: Offset(0, 8),
                                    ),
                                  ],
                                ),
                                child: Padding(
                                  padding: const EdgeInsets.fromLTRB(
                                    16,
                                    14,
                                    16,
                                    14,
                                  ),
                                  child: Text(
                                    page.textContent ?? '',
                                    textAlign: TextAlign.center,
                                    style: GoogleFonts.lora(
                                      color: const Color(0xFFF8FAFC),
                                      fontSize: 22,
                                      fontWeight: FontWeight.w700,
                                      height: 1.38,
                                      shadows: const [
                                        Shadow(
                                          blurRadius: 10,
                                          offset: Offset(0, 2),
                                          color: Color.fromRGBO(0, 0, 0, 0.35),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              )
                              .animate(target: widget.isActive ? 1 : 0)
                              .fadeIn(
                                delay: 120.ms,
                                duration: 340.ms,
                                curve: Curves.easeOut,
                              )
                              .slideY(
                                begin: 0.08,
                                end: 0,
                                delay: 120.ms,
                                duration: 340.ms,
                                curve: Curves.easeOutCubic,
                              ),
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    );
  }
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { useAudioPlayer, type AudioPlayerState } from './useAudioPlayer';
import { useLocalPreferences } from './useLocalPreferences';
import type { PageData } from '@/types';

type UseReaderAudioProps = {
  pageData: PageData | undefined;
  bookId: string;
};

type UseReaderAudioReturn = {
  isNarrationActive: boolean;
  isSoundscapeActive: boolean;
  narrationState: AudioPlayerState;
  soundscapeState: AudioPlayerState;
  toggleNarration: () => Promise<void>;
  toggleSoundscape: () => Promise<void>;
  loadNarration: (url: string) => Promise<void>;
  loadSoundscape: (url: string) => Promise<void>;
  cleanup: () => void;
};

export function useReaderAudio({ pageData }: UseReaderAudioProps): UseReaderAudioReturn {
  const {
    narrationState,
    loadNarration: loadNarrationAudio,
    playNarration,
    pauseNarration,
    soundscapeState,
    loadSoundscape: loadSoundscapeAudio,
    playSoundscape,
    pauseSoundscape,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup: cleanupAudio,
  } = useAudioPlayer();

  const { preferences } = useLocalPreferences();

  const [isNarrationActive, setIsNarrationActive] = useState(false);
  const [isSoundscapeActive, setIsSoundscapeActive] = useState(false);

  const introFadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const introFadedPages = useRef(new Set<number>());
  const prevSoundscapeUrl = useRef<string | null>(null);

  const currentPage = pageData?.pageNumber ?? 1;

  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
  const soundscapeUrl = soundscapeAssignment?.audioUrl;

  // Load narration audio when page changes
  useEffect(() => {
    if (narrationUrl) {
      loadNarrationAudio(narrationUrl).then(() => {
        if (isNarrationActive) {
          playNarration();
        }
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [narrationUrl]);

  // Handle soundscape changes with crossfade
  useEffect(() => {
    if (!soundscapeUrl) return;

    if (prevSoundscapeUrl.current && prevSoundscapeUrl.current !== soundscapeUrl && isSoundscapeActive) {
      crossfadeSoundscape(soundscapeUrl);
    } else if (!prevSoundscapeUrl.current || prevSoundscapeUrl.current !== soundscapeUrl) {
      loadSoundscapeAudio(soundscapeUrl).then(() => {
        if (isSoundscapeActive) playSoundscape();
      });
    }
    prevSoundscapeUrl.current = soundscapeUrl;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [soundscapeUrl]);

  // Intro-only mode: fade out after 10 seconds
  useEffect(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }

    if (
      preferences.soundscapeMode === 'intro-only' &&
      isSoundscapeActive &&
      soundscapeUrl &&
      !introFadedPages.current.has(currentPage)
    ) {
      introFadeTimerRef.current = setTimeout(() => {
        introFadedPages.current.add(currentPage);
        fadeOutSoundscape(3000).then(() => {
          setIsSoundscapeActive(false);
        });
      }, 10000);
    }

    return () => {
      if (introFadeTimerRef.current) clearTimeout(introFadeTimerRef.current);
    };
  }, [currentPage, preferences.soundscapeMode, isSoundscapeActive, soundscapeUrl, fadeOutSoundscape]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanupAudio();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggleNarration = useCallback(async () => {
    if (isNarrationActive) {
      await pauseNarration();
      setIsNarrationActive(false);
    } else if (narrationUrl) {
      await playNarration();
      setIsNarrationActive(true);
    }
  }, [isNarrationActive, narrationUrl, playNarration, pauseNarration]);

  const toggleSoundscape = useCallback(async () => {
    if (isSoundscapeActive) {
      await pauseSoundscape();
      setIsSoundscapeActive(false);
    } else if (soundscapeUrl) {
      await playSoundscape();
      setIsSoundscapeActive(true);
    }
  }, [isSoundscapeActive, soundscapeUrl, playSoundscape, pauseSoundscape]);

  const loadNarration = useCallback(
    async (url: string) => {
      await loadNarrationAudio(url);
    },
    [loadNarrationAudio]
  );

  const loadSoundscape = useCallback(
    async (url: string) => {
      await loadSoundscapeAudio(url);
    },
    [loadSoundscapeAudio]
  );

  const cleanup = useCallback(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }
    cleanupAudio();
  }, [cleanupAudio]);

  return {
    isNarrationActive,
    isSoundscapeActive,
    narrationState,
    soundscapeState,
    toggleNarration,
    toggleSoundscape,
    loadNarration,
    loadSoundscape,
    cleanup,
  };
}

import { useRef, useCallback, useEffect, useState } from 'react';
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

export type AudioPlayerState = {
  isPlaying: boolean;
  positionMs: number;
  durationMs: number;
};

type UseAudioPlayerReturn = {
  // Narration
  narrationState: AudioPlayerState;
  loadNarration: (uri: string) => Promise<void>;
  playNarration: () => Promise<void>;
  pauseNarration: () => Promise<void>;
  seekNarration: (positionMs: number) => Promise<void>;
  setNarrationVolume: (volume: number) => Promise<void>;
  // Soundscape
  soundscapeState: AudioPlayerState;
  loadSoundscape: (uri: string) => Promise<void>;
  playSoundscape: () => Promise<void>;
  pauseSoundscape: () => Promise<void>;
  setSoundscapeVolume: (volume: number) => Promise<void>;
  // Crossfade
  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
  fadeOutSoundscape: (duration?: number) => Promise<void>;
  // Cleanup
  cleanup: () => Promise<void>;
};

export function useAudioPlayer(): UseAudioPlayerReturn {
  const narrationRef = useRef<AudioPlayer | null>(null);
  const soundscapeRef = useRef<AudioPlayer | null>(null);
  const narrationSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
  const soundscapeSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Track the current soundscape volume for fade calculations
  const soundscapeVolumeRef = useRef<number>(0.6);

  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  // Configure audio mode for background playback
  useEffect(() => {
    setAudioModeAsync({
      playsInSilentModeIOS: true,
      staysActiveInBackground: true,
      shouldDuckAndroid: true,
    });
  }, []);

  // Narration controls
  const loadNarration = useCallback(async (uri: string) => {
    // Clean up previous narration player
    if (narrationSubRef.current) {
      narrationSubRef.current.remove();
      narrationSubRef.current = null;
    }
    if (narrationRef.current) {
      narrationRef.current.remove();
      narrationRef.current = null;
    }

    const player = createAudioPlayer({ uri });

    // Subscribe to status updates for word-sync (high frequency)
    narrationSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
      setNarrationState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    narrationRef.current = player;
  }, []);

  const playNarration = useCallback(async () => {
    narrationRef.current?.play();
  }, []);

  const pauseNarration = useCallback(async () => {
    narrationRef.current?.pause();
  }, []);

  const seekNarration = useCallback(async (positionMs: number) => {
    narrationRef.current?.seekTo(positionMs / 1000);
  }, []);

  const setNarrationVolume = useCallback(async (volume: number) => {
    if (narrationRef.current) {
      narrationRef.current.volume = volume;
    }
  }, []);

  // Soundscape controls
  const loadSoundscape = useCallback(async (uri: string) => {
    // Clean up previous soundscape player
    if (soundscapeSubRef.current) {
      soundscapeSubRef.current.remove();
      soundscapeSubRef.current = null;
    }
    if (soundscapeRef.current) {
      soundscapeRef.current.remove();
      soundscapeRef.current = null;
    }

    const player = createAudioPlayer({ uri });
    player.loop = true;
    player.volume = 0.6;
    soundscapeVolumeRef.current = 0.6;

    soundscapeSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
      setSoundscapeState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    soundscapeRef.current = player;
  }, []);

  const playSoundscape = useCallback(async () => {
    soundscapeRef.current?.play();
  }, []);

  const pauseSoundscape = useCallback(async () => {
    soundscapeRef.current?.pause();
  }, []);

  const setSoundscapeVolume = useCallback(async (volume: number) => {
    if (soundscapeRef.current) {
      soundscapeRef.current.volume = volume;
      soundscapeVolumeRef.current = volume;
    }
  }, []);

  // Fade out over duration
  const fadeOutSoundscape = useCallback(async (duration: number = 3000) => {
    const player = soundscapeRef.current;
    if (!player) return;

    const startVolume = soundscapeVolumeRef.current;
    const steps = 20;
    const stepDuration = duration / steps;
    const volumeStep = startVolume / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const newVolume = Math.max(0, startVolume - volumeStep * currentStep);
        player.volume = newVolume;
        soundscapeVolumeRef.current = newVolume;

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
          player.pause();
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Crossfade: fade out current, load new, fade in
  const crossfadeSoundscape = useCallback(async (newUri: string, duration: number = 1500) => {
    const oldPlayer = soundscapeRef.current;
    const oldSub = soundscapeSubRef.current;

    // Create new player at volume 0
    const newPlayer = createAudioPlayer({ uri: newUri });
    newPlayer.loop = true;
    newPlayer.volume = 0;

    // Subscribe new player to status updates
    soundscapeSubRef.current = newPlayer.addListener('playbackStatusUpdate', (status) => {
      setSoundscapeState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    // Start playing new sound
    newPlayer.play();

    // Fade out old, fade in new simultaneously
    const steps = 15;
    const stepDuration = duration / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const progress = currentStep / steps;

        // Fade in new
        newPlayer.volume = 0.6 * progress;

        // Fade out old
        if (oldPlayer) {
          try {
            oldPlayer.volume = 0.6 * (1 - progress);
          } catch {
            // Old player may already be removed
          }
        }

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

          // Cleanup old
          if (oldSub) {
            try { oldSub.remove(); } catch { /* ignore */ }
          }
          if (oldPlayer) {
            try { oldPlayer.remove(); } catch { /* ignore */ }
          }

          soundscapeRef.current = newPlayer;
          soundscapeVolumeRef.current = 0.6;
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Cleanup all audio
  const cleanup = useCallback(async () => {
    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    if (narrationSubRef.current) {
      try { narrationSubRef.current.remove(); } catch { /* ignore */ }
      narrationSubRef.current = null;
    }
    if (narrationRef.current) {
      try { narrationRef.current.remove(); } catch { /* ignore */ }
      narrationRef.current = null;
    }

    if (soundscapeSubRef.current) {
      try { soundscapeSubRef.current.remove(); } catch { /* ignore */ }
      soundscapeSubRef.current = null;
    }
    if (soundscapeRef.current) {
      try { soundscapeRef.current.remove(); } catch { /* ignore */ }
      soundscapeRef.current = null;
    }

    setNarrationState({ isPlaying: false, positionMs: 0, durationMs: 0 });
    setSoundscapeState({ isPlaying: false, positionMs: 0, durationMs: 0 });
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanup();
    };
  }, [cleanup]);

  return {
    narrationState,
    loadNarration,
    playNarration,
    pauseNarration,
    seekNarration,
    setNarrationVolume,
    soundscapeState,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup,
  };
}

import React, { useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { BlurView } from 'expo-blur';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
  withRepeat,
  withSequence,
  Easing,
} from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { fonts } from '@/lib/theme';

// Accent colors
const NARRATION_COLOR = '#F59E0B'; // Warm amber
const NARRATION_GLOW = 'rgba(245, 158, 11, 0.25)';
const SOUNDSCAPE_COLOR = '#14B8A6'; // Teal
const SOUNDSCAPE_GLOW = 'rgba(20, 184, 166, 0.25)';

type Props = {
  hasNarration: boolean;
  hasSoundscape: boolean;
  isNarrationPlaying: boolean;
  isSoundscapePlaying: boolean;
  onToggleNarration: () => void;
  onToggleSoundscape: () => void;
  isVisible?: boolean;
};

/**
 * Pulsing dot indicator that shows when audio is playing.
 */
function PulsingDot({ color, isActive }: { color: string; isActive: boolean }) {
  const pulse = useSharedValue(1);

  useEffect(() => {
    if (isActive) {
      pulse.value = withRepeat(
        withSequence(
          withTiming(0.4, { duration: 800, easing: Easing.inOut(Easing.ease) }),
          withTiming(1, { duration: 800, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        true
      );
    } else {
      pulse.value = withTiming(0, { duration: 200 });
    }
  }, [isActive, pulse]);

  const dotStyle = useAnimatedStyle(() => ({
    opacity: pulse.value,
    transform: [{ scale: 0.6 + pulse.value * 0.4 }],
  }));

  return (
    <Animated.View
      style={[
        {
          position: 'absolute',
          top: 6,
          right: 6,
          width: 6,
          height: 6,
          borderRadius: 3,
          backgroundColor: color,
        },
        dotStyle,
      ]}
    />
  );
}

/**
 * A single circular icon button for audio control.
 */
function AudioIconButton({
  icon,
  accentColor,
  glowColor,
  isPlaying,
  onPress,
}: {
  icon: string;
  accentColor: string;
  glowColor: string;
  isPlaying: boolean;
  onPress: () => void;
}) {
  const glowOpacity = useSharedValue(0);

  useEffect(() => {
    glowOpacity.value = withTiming(isPlaying ? 1 : 0, { duration: 300 });
  }, [isPlaying, glowOpacity]);

  const glowStyle = useAnimatedStyle(() => ({
    opacity: glowOpacity.value,
  }));

  return (
    <TouchableOpacity
      onPress={onPress}
      activeOpacity={0.7}
      hitSlop={12}
      style={styles.iconButtonWrapper}
    >
      {/* Glow ring behind button when active */}
      <Animated.View
        style={[
          styles.glowRing,
          { backgroundColor: glowColor },
          glowStyle,
        ]}
      />
      <View
        style={[
          styles.iconButton,
          isPlaying && {
            borderColor: accentColor,
            borderWidth: 1.5,
          },
        ]}
      >
        <Text
          style={[
            styles.iconText,
            { color: isPlaying ? accentColor : 'rgba(255,255,255,0.7)' },
          ]}
        >
          {icon}
        </Text>
        <PulsingDot color={accentColor} isActive={isPlaying} />
      </View>
    </TouchableOpacity>
  );
}

export const AudioControls = React.memo(function AudioControls({
  hasNarration,
  hasSoundscape,
  isNarrationPlaying,
  isSoundscapePlaying,
  onToggleNarration,
  onToggleSoundscape,
  isVisible = true,
}: Props) {
  const insets = useSafeAreaInsets();
  const hasAudio = hasNarration || hasSoundscape;
  const shouldShow = hasAudio && isVisible;

  const containerStyle = useAnimatedStyle(() => ({
    opacity: withTiming(shouldShow ? 1 : 0, { duration: 300 }),
    transform: [{ translateY: withTiming(shouldShow ? 0 : 16, { duration: 300 }) }],
  }));

  if (!hasAudio) return null;

  return (
    <Animated.View
      style={[
        styles.container,
        { bottom: Math.max(28, insets.bottom + 12) },
        containerStyle,
      ]}
      pointerEvents={shouldShow ? 'auto' : 'none'}
    >
      <BlurView
        intensity={35}
        tint="dark"
        style={styles.pillContainer}
      >
        <View style={styles.buttonsRow}>
          {hasNarration && (
            <AudioIconButton
              icon={isNarrationPlaying ? '\u23F8' : '\uD83C\uDFA4'}
              accentColor={NARRATION_COLOR}
              glowColor={NARRATION_GLOW}
              isPlaying={isNarrationPlaying}
              onPress={onToggleNarration}
            />
          )}
          {hasNarration && hasSoundscape && <View style={styles.divider} />}
          {hasSoundscape && (
            <AudioIconButton
              icon={isSoundscapePlaying ? '\uD83D\uDD0A' : '\uD83C\uDFB5'}
              accentColor={SOUNDSCAPE_COLOR}
              glowColor={SOUNDSCAPE_GLOW}
              isPlaying={isSoundscapePlaying}
              onPress={onToggleSoundscape}
            />
          )}
        </View>
      </BlurView>
    </Animated.View>
  );
});

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    left: 0,
    right: 0,
    zIndex: 40,
    alignItems: 'center',
  },
  pillContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 8,
    paddingVertical: 8,
    borderRadius: 28,
    overflow: 'hidden',
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: 'rgba(255,255,255,0.1)',
  },
  buttonsRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  divider: {
    width: StyleSheet.hairlineWidth,
    height: 24,
    backgroundColor: 'rgba(255,255,255,0.12)',
    marginHorizontal: 4,
  },
  iconButtonWrapper: {
    position: 'relative',
    width: 48,
    height: 48,
    justifyContent: 'center',
    alignItems: 'center',
  },
