import React, { useMemo, useEffect } from 'react';
import { StyleSheet } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
} from 'react-native-reanimated';
import type { WordTimestamp } from '@/types';
import { useThemeColors, fonts } from '@/lib/theme';

type Props = {
  text: string;
  timestamps: WordTimestamp[] | null;
  currentPositionMs: number;
  isPlaying: boolean;
  isActive?: boolean;
  overlayMode?: boolean;
};

function StaggerWord({
  word,
  index,
  isHighlighted,
  highlightBg,
  textColor,
  isActive,
  overlayMode,
}: {
  word: string;
  index: number;
  isHighlighted: boolean;
  highlightBg: string;
  textColor: string;
  isActive: boolean;
  overlayMode?: boolean;
}) {
  const progress = useSharedValue(0);

  useEffect(() => {
    if (isActive) {
      progress.value = 0;
      progress.value = withDelay(
        index * 40,
        withTiming(1, { duration: 300 })
      );
    } else {
      progress.value = 0;
    }
  }, [isActive, index, progress]);

  const animStyle = useAnimatedStyle(() => ({
    opacity: progress.value,
    transform: [{ translateY: (1 - progress.value) * 12 }],
  }));

  return (
    <Animated.Text
      style={[
        overlayMode ? styles.overlayWord : styles.word,
        { color: textColor },
        animStyle,
        isHighlighted && { backgroundColor: highlightBg },
      ]}
    >
      {word}{' '}
    </Animated.Text>
  );
}

export function WordHighlighter({
  text,
  timestamps,
  currentPositionMs,
  isPlaying,
  isActive = true,
  overlayMode = false,
}: Props) {
  const colors = useThemeColors();

  const activeWordIndex = useMemo(() => {
    if (!isPlaying || !timestamps || timestamps.length === 0) return -1;

    const currentTime = currentPositionMs / 1000;
    let foundIndex = -1;

    for (let i = 0; i < timestamps.length; i++) {
      const wordData = timestamps[i];
      const nextWord = timestamps[i + 1];

      if (currentTime >= wordData.start && currentTime <= wordData.end) {
        foundIndex = i;
        break;
      }
      if (nextWord && currentTime > wordData.end && currentTime < nextWord.start) {
        foundIndex = i;
        break;
      }
      if (!nextWord && currentTime >= wordData.start) {
        foundIndex = i;
        break;
      }
      if (currentTime > wordData.end) {
        foundIndex = i;
      }
    }

    return foundIndex;
  }, [currentPositionMs, timestamps, isPlaying]);

  const textColor = overlayMode ? '#ffffff' : colors.readerText;

  if (!timestamps || timestamps.length === 0) {
    // Split plain text into words for stagger animation
    const words = text.split(/\s+/);
    return (
      <Animated.Text style={[overlayMode ? styles.overlayText : styles.text, { fontFamily: fonts.serif }]}>
        {words.map((word, i) => (
          <StaggerWord
            key={i}
            word={word}
            index={i}
            isHighlighted={false}
            highlightBg={colors.readerHighlightBg}
            textColor={textColor}
            isActive={isActive}
            overlayMode={overlayMode}
          />
        ))}
      </Animated.Text>
    );
  }

  return (
    <Animated.Text style={[overlayMode ? styles.overlayText : styles.text, { fontFamily: fonts.serif }]}>
      {timestamps.map((wordData, index) => (
        <StaggerWord
          key={index}
          word={wordData.word}
          index={index}
          isHighlighted={index === activeWordIndex && isPlaying}
          highlightBg={colors.readerHighlightBg}
          textColor={textColor}
          isActive={isActive}
          overlayMode={overlayMode}
        />
      ))}
    </Animated.Text>
  );
}

import { useAnimatedStyle } from 'react-native-reanimated';
import { PageRenderer } from '@/components/PageRenderer';
import type { PageData, WordTimestamp } from '@/types';

interface PageLayerProps {
  page: PageData;
  pageIndex: number;
  activeIndex: number;
  narrationTimestamps: WordTimestamp[] | null;
  currentPositionMs: number;
  isNarrationPlaying: boolean;
  usePageAnimatedStyle: (index: number) => ReturnType<typeof useAnimatedStyle>;
}

export function PageLayer({
  page,
  pageIndex,
  activeIndex,
  narrationTimestamps,
  currentPositionMs,
  isNarrationPlaying,
  usePageAnimatedStyle,
}: PageLayerProps) {
  const animatedStyle = usePageAnimatedStyle(pageIndex);

  return (
    <PageRenderer
      page={page}
      activeWordIndex={-1}
      isActive={pageIndex === activeIndex}
      animatedStyle={animatedStyle}
      narrationTimestamps={narrationTimestamps}
      currentPositionMs={currentPositionMs}
      isNarrationPlaying={isNarrationPlaying}
    />
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import { View, StyleSheet, Dimensions, type LayoutChangeEvent } from 'react-native';
import { Image, type ImageLoadEventData } from 'expo-image';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, { type AnimatedStyle } from 'react-native-reanimated';
import { WordHighlighter } from './WordHighlighter';
import { OverlayTextLayer } from './reader/OverlayTextLayer';
import type { PageData, WordTimestamp } from '@/types';
import { useThemeColors, fonts } from '@/lib/theme';
import { computeContainedImageRect } from '@/lib/textOverlay';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

type Props = {
  page: PageData;
  activeWordIndex: number;
  isActive: boolean;
  animatedStyle: AnimatedStyle;
  narrationTimestamps: WordTimestamp[] | null;
  currentPositionMs: number;
  isNarrationPlaying: boolean;
  onWordTap?: (word: string, globalIndex: number) => void;
  pronouncingWordIndex?: number;
};

export const PageRenderer = React.memo(function PageRenderer({
  page,
  isActive,
  animatedStyle,
  narrationTimestamps,
  currentPositionMs,
  isNarrationPlaying,
  onWordTap,
  pronouncingWordIndex,
}: Props) {
  const colors = useThemeColors();

  // Image measurement state
  const [imageDimensions, setImageDimensions] = useState({ width: 0, height: 0 });
  const [sourceImageDimensions, setSourceImageDimensions] = useState<{ width: number; height: number } | null>(null);

  // Handlers for image measurement
  const onImageLayout = useCallback((event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    setImageDimensions({ width, height });
  }, []);

  const onImageLoad = useCallback((event: ImageLoadEventData) => {
    setSourceImageDimensions({
      width: event.source.width,
      height: event.source.height,
    });
  }, []);

  // Determine display mode
  const hasOverlay = (page.overlay?.elements?.length ?? 0) > 0;
  const hasComposited = !!(page as any).compositedImageUrl;
  const hasFallback = !!page.textContent && !!page.imageUrl;

  // Compute contained image rect when using overlay mode
  const containedRect = useMemo(() => {
    if (!hasOverlay || !sourceImageDimensions) return null;
    return computeContainedImageRect(
      imageDimensions.width,
      imageDimensions.height,
      sourceImageDimensions.width / sourceImageDimensions.height
    );
  }, [hasOverlay, imageDimensions, sourceImageDimensions]);

  // Calculate active word index from narration timestamps
  const computedActiveWordIndex = useMemo(() => {
    if (!isNarrationPlaying || !narrationTimestamps || narrationTimestamps.length === 0) return -1;

    const currentTime = currentPositionMs / 1000;
    let foundIndex = -1;

    for (let i = 0; i < narrationTimestamps.length; i++) {
      const wordData = narrationTimestamps[i];
      const nextWord = narrationTimestamps[i + 1];

      if (currentTime >= wordData.start && currentTime <= wordData.end) {
        foundIndex = i;
        break;
      }
      if (nextWord && currentTime > wordData.end && currentTime < nextWord.start) {
        foundIndex = i;
        break;
      }
      if (!nextWord && currentTime >= wordData.start) {
        foundIndex = i;
        break;
      }
      if (currentTime > wordData.end) {
        foundIndex = i;
      }
    }

    return foundIndex;
  }, [currentPositionMs, narrationTimestamps, isNarrationPlaying]);

  // Determine content fit based on mode
  const contentFit: 'cover' | 'contain' = hasOverlay ? 'contain' : 'cover';

  return (
    <Animated.View style={[styles.page, animatedStyle]}>
      {/* View wrapper with onLayout for measurement */}
      <View style={styles.imageContainer} onLayout={onImageLayout}>
        {/* Full-bleed illustration */}
        {page.imageUrl ? (
          <Image
            source={{ uri: page.imageUrl }}
            style={styles.fullBleedImage}
            contentFit={contentFit}
            transition={isActive ? 300 : 0}
            onLoad={onImageLoad}
          />
        ) : (
          <View style={[styles.fullBleedImage, { backgroundColor: colors.readerCardBg }]} />
        )}

        {/* DYNAMIC OVERLAY mode: Render OverlayTextLayer positioned at containedRect */}
        {hasOverlay && containedRect && page.overlay && (
          <View
            style={[
              styles.overlayLayer,
              {
                left: containedRect.x,
                top: containedRect.y,
                width: containedRect.width,
                height: containedRect.height,
              },
            ]}
          >
            <OverlayTextLayer
              overlay={page.overlay}
              imageWidth={containedRect.width}
              imageHeight={containedRect.height}
              activeWordIndex={computedActiveWordIndex}
              pronouncingWordIndex={pronouncingWordIndex}
              isActive={isActive}
              onWordTap={onWordTap}
            />
          </View>
        )}

        {/* COMPOSITED mode: No additional overlay components needed */}
        {/* Image is already rendered above with contentFit="cover" */}

        {/* FALLBACK mode: Gradient scrims + WordHighlighter at bottom */}
        {!hasOverlay && !hasComposited && hasFallback && page.textContent && (
          <>
            {/* Gradient scrim for text readability */}
            <LinearGradient
              colors={['transparent', 'rgba(0,0,0,0.5)', 'rgba(0,0,0,0.85)']}
              locations={[0, 0.3, 1]}
              style={styles.gradientScrim}
            />
            <LinearGradient
              colors={['transparent', 'rgba(0,0,0,0.3)']}
              locations={[0.5, 1]}
              style={[styles.gradientScrim, { height: SCREEN_HEIGHT * 0.25 }]}
            />

            {/* Overlaid text at bottom */}
            <View style={styles.textOverlay}>
              <WordHighlighter
                text={page.textContent}
                timestamps={narrationTimestamps}
                currentPositionMs={currentPositionMs}
                isPlaying={isActive && isNarrationPlaying}
                isActive={isActive}
                overlayMode
              />
            </View>
          </>
        )}

        {/* IMAGE ONLY mode: Just image, no text - already rendered above */}
      </View>
    </Animated.View>
  );
});

const styles = StyleSheet.create({
  page: {
    ...StyleSheet.absoluteFillObject,
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  imageContainer: {
    ...StyleSheet.absoluteFillObject,
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  fullBleedImage: {
    ...StyleSheet.absoluteFillObject,
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  overlayLayer: {
    position: 'absolute',
  },
  gradientScrim: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    height: SCREEN_HEIGHT * 0.55,
  },
  textOverlay: {
    position: 'absolute',
    bottom: 140,
    left: 28,
    right: 28,
  },
});

import React, { useEffect } from 'react';
import { Text, View, StyleSheet, Pressable, type TextStyle, type ViewStyle } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
  Easing,
} from 'react-native-reanimated';
import type { TextElement } from '@/types';
import { resolveFont } from '@/lib/textOverlay';

interface OverlayTextElementProps {
  element: TextElement;
  elementIndex: number;
  imageWidth: number;
  imageHeight: number;
  wordStartIndex: number;
  activeWordIndex?: number;
  pronouncingWordIndex?: number | null;
  isActive: boolean;
  onWordTap?: (word: string, globalIndex: number) => void;
}

export function OverlayTextElement({
  element,
  elementIndex,
  imageWidth,
  imageHeight,
  wordStartIndex,
  activeWordIndex,
  pronouncingWordIndex,
  isActive,
  onWordTap,
}: OverlayTextElementProps) {
  // Animation value
  const progress = useSharedValue(0);

  // Stagger entrance animation
  useEffect(() => {
    if (isActive) {
      const delay = 180 + elementIndex * 40;
      progress.value = withDelay(
        delay,
        withTiming(1, {
          duration: 350,
          easing: Easing.out(Easing.ease),
        })
      );
    } else {
      // Reset immediately when inactive
      progress.value = 0;
    }
  }, [isActive, elementIndex, progress]);

  // Animated style for container
  const animatedStyle = useAnimatedStyle(() => ({
    opacity: progress.value,
    transform: [{ translateY: (1 - progress.value) * 16 }],
  }));

  // Convert percentage to pixels
  const x = (element.x / 100) * imageWidth;
  const y = (element.y / 100) * imageHeight;
  const width = (element.width / 100) * imageWidth;

  // Resolve font family (weight encoded in name)
  const fontFamily = resolveFont(element.fontFamily, element.fontWeight);

  // Calculate font size based on image height (assuming 100% = full image height)
  const fontSize = (element.fontSize / 100) * imageHeight;

  // Build text style
  const textStyle: TextStyle = {
    fontFamily,
    fontSize,
    color: element.color,
    textAlign: element.textAlign,
    lineHeight: fontSize * 1.3,
  };

  // Shadow style
  const shadowStyle: TextStyle = element.shadow
    ? {
        textShadowColor: element.shadow.color,
        textShadowOffset: { width: element.shadow.x, height: element.shadow.y },
        textShadowRadius: element.shadow.blur,
      }
    : {};

  // Container styles
  const containerStyle: ViewStyle = {
    position: 'absolute',
    left: x,
    top: y,
    width,
    transform: element.rotation !== 0 ? [{ rotate: `${element.rotation}deg` }] : undefined,
  };

  // Background container style
  const backgroundStyle: ViewStyle = element.background
    ? {
        backgroundColor: element.background.color,
        padding: element.background.padding || 0,
        borderRadius: element.background.borderRadius || 0,
      }
    : {};

  // Split text into tokens (preserving whitespace)
  const tokens = element.text.split(/(\s+)/);

  // Check if a word is highlighted
  const isWordHighlighted = (globalIndex: number): boolean => {
    if (activeWordIndex !== undefined && globalIndex === activeWordIndex) {
      return true;
    }
    if (pronouncingWordIndex !== null && pronouncingWordIndex !== undefined && globalIndex === pronouncingWordIndex) {
      return true;
    }
    return false;
  };

  // Word index tracker
  let currentWordIndex = wordStartIndex;

  return (
    <Animated.View style={[containerStyle, animatedStyle]} pointerEvents="box-none">
      <View style={backgroundStyle}>
        <Text style={[textStyle, shadowStyle]}>
          {tokens.map((token, tokenIndex) => {
            // Check if token is whitespace
            if (/^\s+$/.test(token)) {
              return token;
            }

            // It's a word
            const globalIndex = currentWordIndex;
            const isHighlighted = isWordHighlighted(globalIndex);
            currentWordIndex++;

            const wordStyle: TextStyle = isHighlighted
              ? {
                  backgroundColor: 'rgba(212, 237, 188, 0.8)',
                  borderRadius: 4,
                  paddingHorizontal: 2,
                }
              : {};

            if (onWordTap) {
              return (
                <Pressable
                  key={tokenIndex}
                  onPress={() => onWordTap(token, globalIndex)}
                  style={styles.pressableWord}
                >
                  <Text style={[textStyle, shadowStyle, wordStyle]}>{token}</Text>
                </Pressable>
              );
            }

            return (
              <Text key={tokenIndex} style={[textStyle, shadowStyle, wordStyle]}>
                {token}
              </Text>
            );
          })}
        </Text>
      </View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  pressableWord: {
    display: 'flex',
  },
});

import React, { useMemo } from 'react';
import { View } from 'react-native';
import type { TextOverlayConfig } from '@/types';
import { calculateWordStartsByElementId } from '@/lib/textOverlay';
import { OverlayTextElement } from './OverlayTextElement';

interface OverlayTextLayerProps {
  overlay: TextOverlayConfig;
  imageWidth: number;
  imageHeight: number;
  activeWordIndex?: number;
  pronouncingWordIndex?: number | null;
  isActive: boolean;
  onWordTap?: (word: string, globalIndex: number) => void;
}

export function OverlayTextLayer({
  overlay,
  imageWidth,
  imageHeight,
  activeWordIndex,
  pronouncingWordIndex,
  isActive,
  onWordTap,
}: OverlayTextLayerProps) {
  // Compute global word start indices for each element
  const wordStartsByElementId = useMemo(() => {
    return calculateWordStartsByElementId(overlay);
  }, [overlay]);

  // Return null if dimensions are invalid
  if (imageWidth === 0 || imageHeight === 0) {
    return null;
  }

  return (
    <View
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: imageWidth,
        height: imageHeight,
      }}
      pointerEvents="box-none"
    >
      {overlay.elements.map((element, index) => (
        <OverlayTextElement
          key={element.id}
          element={element}
          elementIndex={index}
          imageWidth={imageWidth}
          imageHeight={imageHeight}
          wordStartIndex={wordStartsByElementId.get(element.id) ?? 0}
          activeWordIndex={activeWordIndex}
          pronouncingWordIndex={pronouncingWordIndex}
          isActive={isActive}
          onWordTap={onWordTap}
        />
      ))}
    </View>
  );
}

