import 'package:flutter/foundation.dart';

class WordTimestamp {
  final String word;
  final double start;
  final double end;

  const WordTimestamp({
    required this.word,
    required this.start,
    required this.end,
  });

  factory WordTimestamp.fromJson(Map<String, dynamic> json) {
    return WordTimestamp(
      word: json['word'] as String? ?? '',
      start: (json['start'] as num?)?.toDouble() ?? 0,
      end: (json['end'] as num?)?.toDouble() ?? 0,
    );
  }
}

class TextElement {
  final String id;
  final String text;
  final double x;
  final double y;
  final double width;
  final String fontFamily;
  final double fontSize;
  final int fontWeight;
  final String color;
  final String textAlign;
  final double rotation;
  final TextShadow? shadow;
  final TextBackground? background;

  const TextElement({
    required this.id,
    required this.text,
    required this.x,
    required this.y,
    required this.width,
    required this.fontFamily,
    required this.fontSize,
    required this.fontWeight,
    required this.color,
    required this.textAlign,
    required this.rotation,
    this.shadow,
    this.background,
  });

  factory TextElement.fromJson(Map<String, dynamic> json) {
    return TextElement(
      id: json['id'] as String? ?? '',
      text: json['text'] as String? ?? '',
      x: (json['x'] as num?)?.toDouble() ?? 0,
      y: (json['y'] as num?)?.toDouble() ?? 0,
      width: (json['width'] as num?)?.toDouble() ?? 0,
      fontFamily: json['fontFamily'] as String? ?? 'Inter',
      fontSize: (json['fontSize'] as num?)?.toDouble() ?? 0,
      fontWeight: (json['fontWeight'] as num?)?.toInt() ?? 400,
      color: json['color'] as String? ?? '#FFFFFF',
      textAlign: json['textAlign'] as String? ?? 'left',
      rotation: (json['rotation'] as num?)?.toDouble() ?? 0,
      shadow: json['shadow'] is Map<String, dynamic>
          ? TextShadow.fromJson(json['shadow'] as Map<String, dynamic>)
          : null,
      background: json['background'] is Map<String, dynamic>
          ? TextBackground.fromJson(json['background'] as Map<String, dynamic>)
          : null,
    );
  }
}

class TextShadow {
  final String color;
  final double blur;
  final double x;
  final double y;

  const TextShadow({
    required this.color,
    required this.blur,
    required this.x,
    required this.y,
  });

  factory TextShadow.fromJson(Map<String, dynamic> json) {
    return TextShadow(
      color: json['color'] as String? ?? '#000000',
      blur: (json['blur'] as num?)?.toDouble() ?? 0,
      x: (json['x'] as num?)?.toDouble() ?? 0,
      y: (json['y'] as num?)?.toDouble() ?? 0,
    );
  }
}

class TextBackground {
  final String color;
  final double? padding;
  final double? borderRadius;

  const TextBackground({required this.color, this.padding, this.borderRadius});

  factory TextBackground.fromJson(Map<String, dynamic> json) {
    return TextBackground(
      color: json['color'] as String? ?? '#000000',
      padding: (json['padding'] as num?)?.toDouble(),
      borderRadius: (json['borderRadius'] as num?)?.toDouble(),
    );
  }
}

class TextOverlayConfig {
  final int version;
  final List<TextElement> elements;

  const TextOverlayConfig({required this.version, required this.elements});

  factory TextOverlayConfig.fromJson(Map<String, dynamic> json) {
    final elements = (json['elements'] as List<dynamic>? ?? <dynamic>[])
        .whereType<Map<String, dynamic>>()
        .map(TextElement.fromJson)
        .toList();

    return TextOverlayConfig(
      version: (json['version'] as num?)?.toInt() ?? 1,
      elements: elements,
    );
  }
}

class PageData {
  final String id;
  final int pageNumber;
  final String? textContent;
  final TextOverlayConfig? overlay;
  final String? imageUrl;
  final String? narrationUrl;
  final String? soundscapeUrl;
  final String? compositedImageUrl;
  final List<WordTimestamp>? narrationTimestamps;

  const PageData({
    required this.id,
    required this.pageNumber,
    this.textContent,
    this.overlay,
    this.imageUrl,
    this.narrationUrl,
    this.soundscapeUrl,
    this.compositedImageUrl,
    this.narrationTimestamps,
  });

  factory PageData.fromJson(Map<String, dynamic> json) {
    final rawTimestamps =
        json['narration_timestamps'] ?? json['narrationTimestamps'];
    final timestamps = rawTimestamps is List
        ? rawTimestamps
              .whereType<Map<String, dynamic>>()
              .map(WordTimestamp.fromJson)
              .toList()
        : null;

    final overlayJson = json['text_overlay'];

    // Soundscape URL is derived from the nested scenes -> soundscapes relation.
    // Prefer admin-approved soundscapes, fall back to first available.
    String? soundscapeUrl;
    final scenesData = json['scenes'];
    if (scenesData is Map<String, dynamic>) {
      final rawSoundscapes = scenesData['soundscapes'];
      if (rawSoundscapes is List && rawSoundscapes.isNotEmpty) {
        final soundscapes = rawSoundscapes
            .whereType<Map<String, dynamic>>()
            .toList();
        final approved = soundscapes
            .where((s) => s['admin_approved'] == true)
            .toList();
        final chosen = approved.isNotEmpty ? approved.first : soundscapes.first;
        soundscapeUrl = chosen['audio_url'] as String?;
      }
    }

    return PageData(
      id: json['id']?.toString() ?? '',
      pageNumber: _parsePageNumber(json),
      textContent:
          json['text_content'] as String? ?? json['textContent'] as String?,
      overlay: overlayJson is Map<String, dynamic>
          ? TextOverlayConfig.fromJson(overlayJson)
          : null,
      imageUrl: json['image_url'] as String? ?? json['imageUrl'] as String?,
      narrationUrl:
          json['narration_url'] as String? ?? json['narrationUrl'] as String?,
      soundscapeUrl: soundscapeUrl,
      compositedImageUrl:
          json['composited_image_url'] as String? ??
          json['compositedImageUrl'] as String?,
      narrationTimestamps: timestamps,
    );
  }
}

class Book {
  final String id;
  final String title;
  final String? author;
  final String? coverUrl;
  final List<PageData> pages;

  const Book({
    required this.id,
    required this.title,
    this.author,
    this.coverUrl,
    required this.pages,
  });

  factory Book.fromJson(Map<String, dynamic> json) {
    final parsedPages = (json['pages'] as List<dynamic>? ?? <dynamic>[])
        .whereType<Map<String, dynamic>>()
        .map(PageData.fromJson)
        .toList();

    final pages = _sortedPages(parsedPages);
    assert(() {
      if (_isDifferentOrder(parsedPages, pages)) {
        debugPrint(
          '[Book.fromJson] Incoming page order was unsorted for book '
          '${json['id'] ?? ''}. Applying deterministic sort by pageNumber/id.',
        );
      }
      return true;
    }());

    return Book(
      id: json['id']?.toString() ?? '',
      title: json['title'] as String? ?? '',
      author: json['author'] as String?,
      coverUrl: json['cover_url'] as String? ?? json['coverUrl'] as String?,
      pages: pages,
    );
  }
}

const int _invalidPageNumber = 1 << 30;

int _parsePageNumber(Map<String, dynamic> json) {
  final rawPageNumber = json['page_number'] ?? json['pageNumber'];
  if (rawPageNumber is num) {
    final pageNumber = rawPageNumber.toInt();
    return pageNumber > 0 ? pageNumber : _invalidPageNumber;
  }
  if (rawPageNumber is String) {
    final pageNumber = int.tryParse(rawPageNumber);
    if (pageNumber == null || pageNumber <= 0) {
      return _invalidPageNumber;
    }
    return pageNumber;
  }
  return _invalidPageNumber;
}

List<PageData> _sortedPages(List<PageData> pages) {
  final indexedPages = pages.asMap().entries.toList();
  indexedPages.sort((a, b) {
    final pageNumberCompare = a.value.pageNumber.compareTo(b.value.pageNumber);
    if (pageNumberCompare != 0) {
      return pageNumberCompare;
    }

    final idCompare = a.value.id.compareTo(b.value.id);
    if (idCompare != 0) {
      return idCompare;
    }

    return a.key.compareTo(b.key);
  });

  return indexedPages.map((entry) => entry.value).toList(growable: false);
}

bool _isDifferentOrder(List<PageData> original, List<PageData> sorted) {
  if (identical(original, sorted)) {
    return false;
  }
  if (original.length != sorted.length) {
    return true;
  }
  for (var i = 0; i < original.length; i++) {
    if (!identical(original[i], sorted[i])) {
      return true;
    }
  }
  return false;
}

import React, { useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { BlurView } from 'expo-blur';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
  withRepeat,
  withSequence,
  Easing,
} from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { fonts } from '@/lib/theme';

// Accent colors
const NARRATION_COLOR = '#F59E0B'; // Warm amber
const NARRATION_GLOW = 'rgba(245, 158, 11, 0.25)';
const SOUNDSCAPE_COLOR = '#14B8A6'; // Teal
const SOUNDSCAPE_GLOW = 'rgba(20, 184, 166, 0.25)';

type Props = {
  hasNarration: boolean;
  hasSoundscape: boolean;
  isNarrationPlaying: boolean;
  isSoundscapePlaying: boolean;
  onToggleNarration: () => void;
  onToggleSoundscape: () => void;
  isVisible?: boolean;
};

/**
 * Pulsing dot indicator that shows when audio is playing.
 */
function PulsingDot({ color, isActive }: { color: string; isActive: boolean }) {
  const pulse = useSharedValue(1);

  useEffect(() => {
    if (isActive) {
      pulse.value = withRepeat(
        withSequence(
          withTiming(0.4, { duration: 800, easing: Easing.inOut(Easing.ease) }),
          withTiming(1, { duration: 800, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        true
      );
    } else {
      pulse.value = withTiming(0, { duration: 200 });
    }
  }, [isActive, pulse]);

  const dotStyle = useAnimatedStyle(() => ({
    opacity: pulse.value,
    transform: [{ scale: 0.6 + pulse.value * 0.4 }],
  }));

  return (
    <Animated.View
      style={[
        {
          position: 'absolute',
          top: 6,
          right: 6,
          width: 6,
          height: 6,
          borderRadius: 3,
          backgroundColor: color,
        },
        dotStyle,
      ]}
    />
  );
}

/**
 * A single circular icon button for audio control.
 */
function AudioIconButton({
  icon,
  accentColor,
  glowColor,
  isPlaying,
  onPress,
}: {
  icon: string;
  accentColor: string;
  glowColor: string;
  isPlaying: boolean;
  onPress: () => void;
}) {
  const glowOpacity = useSharedValue(0);

  useEffect(() => {
    glowOpacity.value = withTiming(isPlaying ? 1 : 0, { duration: 300 });
  }, [isPlaying, glowOpacity]);

  const glowStyle = useAnimatedStyle(() => ({
    opacity: glowOpacity.value,
  }));

  return (
    <TouchableOpacity
      onPress={onPress}
      activeOpacity={0.7}
      hitSlop={12}
      style={styles.iconButtonWrapper}
    >
      {/* Glow ring behind button when active */}
      <Animated.View
        style={[
          styles.glowRing,
          { backgroundColor: glowColor },
          glowStyle,
        ]}
      />
      <View
        style={[
          styles.iconButton,
          isPlaying && {
            borderColor: accentColor,
            borderWidth: 1.5,
          },
        ]}
      >
        <Text
          style={[
            styles.iconText,
            { color: isPlaying ? accentColor : 'rgba(255,255,255,0.7)' },
          ]}
        >
          {icon}
        </Text>
        <PulsingDot color={accentColor} isActive={isPlaying} />
      </View>
    </TouchableOpacity>
  );
}

export const AudioControls = React.memo(function AudioControls({
  hasNarration,
  hasSoundscape,
  isNarrationPlaying,
  isSoundscapePlaying,
  onToggleNarration,
  onToggleSoundscape,
  isVisible = true,
}: Props) {
  const insets = useSafeAreaInsets();
  const hasAudio = hasNarration || hasSoundscape;
  const shouldShow = hasAudio && isVisible;

  const containerStyle = useAnimatedStyle(() => ({
    opacity: withTiming(shouldShow ? 1 : 0, { duration: 300 }),
    transform: [{ translateY: withTiming(shouldShow ? 0 : 16, { duration: 300 }) }],
  }));

  if (!hasAudio) return null;

  return (
    <Animated.View
      style={[
        styles.container,
        { bottom: Math.max(28, insets.bottom + 12) },
        containerStyle,
      ]}
      pointerEvents={shouldShow ? 'auto' : 'none'}
    >
      <BlurView
        intensity={35}
        tint="dark"
        style={styles.pillContainer}
      >
        <View style={styles.buttonsRow}>
          {hasNarration && (
            <AudioIconButton
              icon={isNarrationPlaying ? '\u23F8' : '\uD83C\uDFA4'}
              accentColor={NARRATION_COLOR}
              glowColor={NARRATION_GLOW}
              isPlaying={isNarrationPlaying}
              onPress={onToggleNarration}
            />
          )}
          {hasNarration && hasSoundscape && <View style={styles.divider} />}
          {hasSoundscape && (
            <AudioIconButton
              icon={isSoundscapePlaying ? '\uD83D\uDD0A' : '\uD83C\uDFB5'}
              accentColor={SOUNDSCAPE_COLOR}
              glowColor={SOUNDSCAPE_GLOW}
              isPlaying={isSoundscapePlaying}
              onPress={onToggleSoundscape}
            />
          )}
        </View>
      </BlurView>
    </Animated.View>
  );
});

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    left: 0,
    right: 0,
    zIndex: 40,
    alignItems: 'center',
  },
  pillContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 8,
    paddingVertical: 8,
    borderRadius: 28,
    overflow: 'hidden',
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: 'rgba(255,255,255,0.1)',
  },
  buttonsRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  divider: {
    width: StyleSheet.hairlineWidth,
    height: 24,
    backgroundColor: 'rgba(255,255,255,0.12)',
    marginHorizontal: 4,
  },
  iconButtonWrapper: {
    position: 'relative',
    width: 48,
    height: 48,
    justifyContent: 'center',
    alignItems: 'center',
  },
  glowRing: {
    position: 'absolute',
    width: 48,
    height: 48,
    borderRadius: 24,
  },
  iconButton: {
    width: 44,
    height: 44,
    borderRadius: 22,
    backgroundColor: 'rgba(255,255,255,0.06)',
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: 'rgba(255,255,255,0.08)',
  },
  iconText: {
    fontSize: 20,
  },
});

