                          fontWeight: FontWeight.w600,
                          color: const Color(0xFFD4D8E0),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(width: 10),
              _ChromeButton(
                icon: Icons.tune_rounded,
